import { useSpring, config } from '@react-spring/web'

const springs = useSpring({
  from: { opacity: 0 },
  to: { opacity: 1 },
  config: config.gentle  // Smooth, elegant motion
})

const springs = useSpring({
  from: { x: 0 },
  to: { x: 100 },
  config: {
    mass: 1,       // Standard weight
    tension: 170,  // Moderate stiffness
    friction: 26,  // Balanced damping
  }
})

const springs = useSpring({
  from: { scale: 0 },
  to: { scale: 1 },
  config: {
    frequency: 2,    // 2 oscillations per second
    damping: 0.5,    // Underdamped (bouncy)
  }
})

import { easings } from '@react-spring/web'

const springs = useSpring({
  from: { y: -100 },
  to: { y: 0 },
  config: {
    duration: 1000,                    // 1 second
    easing: easings.easeOutCubic,     // Smooth deceleration
  }
})

const springs = useSpring({
  from: { x: 0, opacity: 0 },
  to: { x: 100, opacity: 1 },
  config: key => {
    if (key === 'x') {
      return { tension: 210, friction: 20 }  // Fast movement
    }
    if (key === 'opacity') {
      return { duration: 500 }               // Timed fade
    }
  }
})

const [{ x }, api] = useSpring(() => ({ x: 0 }))

const handleDrag = (velocity) => {
  api.start({
    x: x.get() + velocity * 100,  // Project based on velocity
    config: {
      decay: true,                 // Natural deceleration
      velocity: velocity,          // Initial velocity from gesture
    }
  })
}

const springs = useSpring({
  from: { width: 0 },
  to: { width: 200 },
  config: {
    tension: 170,
    friction: 26,
    clamp: true,     // Stop exactly at 200px (no bounce)
  }
})
